"""Redis ACL users generated by deploy/compose/redis/entrypoint.sh (PAY-607, R12, C3, C27)."""

from __future__ import annotations

import pytest
import redis
from pycommon.testing import RedisAcl
from redis.exceptions import NoPermissionError

pytestmark = pytest.mark.integration

STREAM = "stream:payout.requested"
DLQ = "stream:payout.requested.dlq"


def _client(acl: RedisAcl, user: str) -> redis.Redis:
    e = acl.env_for(user)
    return redis.Redis(
        host=e["REDIS_HOST"],
        port=int(e["REDIS_PORT"]),
        username=e["REDIS_USERNAME"],
        password=e["REDIS_PASSWORD"],
    )


@pytest.mark.parametrize("user", ["web", "identity"])
def test_web_and_identity_cannot_publish_payouts_or_run_lua(redis_acl: RedisAcl, user: str) -> None:
    """PAY-607, C3: only payroll may XADD the payout stream; scripting is denied."""
    r = _client(redis_acl, user)
    assert r.set(f"{user}:platform-test", "1")
    with pytest.raises(NoPermissionError):
        r.xadd(STREAM, {"f": "v"})
    with pytest.raises(NoPermissionError):
        r.eval("return 1", 0)
    with pytest.raises(NoPermissionError):
        r.set("payroll:not-mine", "1")


def test_payroll_publishes_but_cannot_consume(redis_acl: RedisAcl) -> None:
    """PAY-607: payroll XADDs the three R7 fields but can't read the stream."""
    r = _client(redis_acl, "payroll")
    assert r.xadd(STREAM, {"event_id": "e", "type": "payout.requested", "envelope": "{}"})
    with pytest.raises(NoPermissionError):
        r.xreadgroup("g", "c", {STREAM: ">"})


def _groups(r: redis.Redis) -> list[dict[str, object]]:
    try:
        return list(r.xinfo_groups(STREAM))
    except redis.ResponseError:  # no such key yet
        return []


def test_worker_consumer_group_lifecycle_and_dlq(redis_acl: RedisAcl) -> None:
    """PAY-607, R12, C27: MKSTREAM, read, claim, DELCONSUMER, DLQ; no main-stream writes."""
    r = _client(redis_acl, "payout-worker")
    assert r.ping()
    if not any(g["name"] == b"payout-worker" for g in _groups(r)):
        r.xgroup_create(STREAM, "payout-worker", id="0", mkstream=True)
    r.xreadgroup("payout-worker", "c1", {STREAM: ">"}, count=1)
    r.xautoclaim(STREAM, "payout-worker", "c2", min_idle_time=0)
    r.xgroup_delconsumer(STREAM, "payout-worker", "c1")
    assert r.xadd(DLQ, {"envelope": "{}"}, maxlen=10000, approximate=True)
    with pytest.raises(NoPermissionError):
        r.xadd(STREAM, {"f": "v"})


def test_exporter_is_read_only(redis_acl: RedisAcl) -> None:
    """PAY-607, R12: the exporter can read stream lengths and nothing else."""
    r = _client(redis_acl, "exporter")
    r.xlen(STREAM)
    with pytest.raises(NoPermissionError):
        r.set("stream:x", "1")
